<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      color-scheme: light;
      font-family: Arial, sans-serif;
      color: #222;
      background: #f4f6f8;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 24px;
    }

    main {
      max-width: 900px;
      margin: 0 auto;
    }

    h1, h2 {
      margin-top: 0;
    }

    .panel {
      background: #fff;
      border: 1px solid #d9dee3;
      border-radius: 8px;
      padding: 20px;
      margin-bottom: 20px;
      box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    }

    form,
    .filters {
      display: grid;
      gap: 12px;
    }

    form {
      grid-template-columns: repeat(4, 1fr);
      align-items: end;
    }

    .field {
      display: flex;
      flex-direction: column;
      gap: 5px;
    }

    label {
      font-weight: 600;
      font-size: 0.9rem;
    }

    input,
    select,
    button {
      font: inherit;
      min-height: 38px;
      border: 1px solid #bbc4cc;
      border-radius: 5px;
      padding: 7px 9px;
    }

    button {
      cursor: pointer;
      background: #1769aa;
      color: #fff;
      border-color: #1769aa;
      font-weight: 600;
    }

    button:hover {
      background: #12588e;
    }

    .error {
      color: #b42318;
      min-height: 1.2em;
      margin: 12px 0 0;
      font-weight: 600;
    }

    .filters {
      grid-template-columns: repeat(3, 1fr);
    }

    .summary {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 18px;
    }

    .summary-card {
      background: #f1f5f9;
      border-radius: 6px;
      padding: 10px 14px;
      min-width: 130px;
    }

    .summary-card strong {
      display: block;
      font-size: 1.15rem;
      margin-top: 4px;
    }

    .total {
      font-size: 1.25rem;
      font-weight: 700;
      margin: 0;
    }

    .expense-list {
      display: grid;
      gap: 10px;
    }

    .expense {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      border: 1px solid #d9dee3;
      border-radius: 6px;
      padding: 12px;
      background: #fff;
    }

    .expense-info {
      display: flex;
      flex-wrap: wrap;
      gap: 8px 16px;
      align-items: baseline;
    }

    .expense-amount {
      font-weight: 700;
      font-size: 1.05rem;
    }

    .expense-category {
      text-transform: capitalize;
      color: #39434d;
    }

    .expense-date {
      color: #66717c;
      font-size: 0.92rem;
    }

    .expense-note {
      width: 100%;
      color: #59636d;
      font-size: 0.9rem;
    }

    .exp-del {
      flex: 0 0 auto;
      background: #b42318;
      border-color: #b42318;
      padding: 6px 10px;
      min-height: 34px;
    }

    .exp-del:hover {
      background: #8f1c13;
    }

    .empty {
      color: #66717c;
      margin: 0;
    }

    @media (max-width: 700px) {
      body {
        padding: 12px;
      }

      form,
      .filters {
        grid-template-columns: 1fr;
      }

      .expense {
        align-items: flex-start;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Personal Expense Tracker</h1>

    <section class="panel" aria-labelledby="add-heading">
      <h2 id="add-heading">Add expense</h2>
      <form id="expense-form" novalidate>
        <div class="field">
          <label for="amount">Amount</label>
          <input id="amount" name="amount" type="number" step="0.01" min="0.01" inputmode="decimal">
        </div>

        <div class="field">
          <label for="category">Category</label>
          <select id="category" name="category">
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </div>

        <div class="field">
          <label for="date">Date</label>
          <input id="date" name="date" type="date">
        </div>

        <div class="field">
          <label for="note">Note <span aria-hidden="true">(optional)</span></label>
          <input id="note" name="note" type="text">
        </div>

        <button id="add-expense" type="submit">Add expense</button>
      </form>
      <p id="form-error" class="error" role="alert"></p>
    </section>

    <section class="panel" aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <p>Total: <span id="total">0.00</span></p>
      <div class="summary" id="category-summary">
        <div class="summary-card cat-total" data-cat="groceries">
          Groceries: <strong>0.00</strong>
        </div>
        <div class="summary-card cat-total" data-cat="transport">
          Transport: <strong>0.00</strong>
        </div>
        <div class="summary-card cat-total" data-cat="bills">
          Bills: <strong>0.00</strong>
        </div>
        <div class="summary-card cat-total" data-cat="fun">
          Fun: <strong>0.00</strong>
        </div>
      </div>
    </section>

    <section class="panel" aria-labelledby="filter-heading">
      <h2 id="filter-heading">Filter expenses</h2>
      <div class="filters">
        <div class="field">
          <label for="filter-category">Category</label>
          <select id="filter-category">
            <option value="all">All categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </div>

        <div class="field">
          <label for="filter-from">From</label>
          <input id="filter-from" type="date">
        </div>

        <div class="field">
          <label for="filter-to">To</label>
          <input id="filter-to" type="date">
        </div>
      </div>
    </section>

    <section class="panel" aria-labelledby="expenses-heading">
      <h2 id="expenses-heading">Expenses</h2>
      <div id="expense-list" class="expense-list"></div>
      <p id="empty-message" class="empty">No expenses yet.</p>
    </section>
  </main>

  <script>
    (function () {
      "use strict";

      const STORAGE_KEY = "personal-expense-tracker-expenses";
      const categories = ["groceries", "transport", "bills", "fun"];

      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const formError = document.getElementById("form-error");
      const expenseList = document.getElementById("expense-list");
      const emptyMessage = document.getElementById("empty-message");
      const totalElement = document.getElementById("total");
      const filterCategory = document.getElementById("filter-category");
      const filterFrom = document.getElementById("filter-from");
      const filterTo = document.getElementById("filter-to");

      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
          if (!Array.isArray(saved)) return [];
          return saved.filter(function (item) {
            return item &&
              typeof item.amount === "number" &&
              Number.isFinite(item.amount) &&
              item.amount > 0 &&
              categories.includes(item.category) &&
              typeof item.date === "string" &&
              item.date !== "";
          });
        } catch (error) {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
      }

      function formatAmount(value) {
        return Number(value).toFixed(2);
      }

      function isVisible(expense) {
        const selectedCategory = filterCategory.value;
        const from = filterFrom.value;
        const to = filterTo.value;

        if (selectedCategory !== "all" && expense.category !== selectedCategory) {
          return false;
        }
        if (from && expense.date < from) {
          return false;
        }
        if (to && expense.date > to) {
          return false;
        }
        return true;
      }

      function render() {
        expenseList.innerHTML = "";
        const categoryTotals = {
          groceries: 0,
          transport: 0,
          bills: 0,
          fun: 0
        };
        let visibleTotal = 0;
        let visibleCount = 0;

        expenses.forEach(function (expense) {
          const visible = isVisible(expense);
          const row = document.createElement("article");
          row.className = "expense";
          row.dataset.id = expense.id;
          row.style.display = visible ? "" : "none";

          const info = document.createElement("div");
          info.className = "expense-info";

          const amount = document.createElement("span");
          amount.className = "expense-amount";
          amount.textContent = formatAmount(expense.amount);

          const category = document.createElement("span");
          category.className = "expense-category";
          category.textContent = expense.category;

          const date = document.createElement("span");
          date.className = "expense-date";
          date.textContent = expense.date;

          info.appendChild(amount);
          info.appendChild(category);
          info.appendChild(date);

          if (expense.note) {
            const note = document.createElement("span");
            note.className = "expense-note";
            note.textContent = expense.note;
            info.appendChild(note);
          }

          const deleteButton = document.createElement("button");
          deleteButton.className = "exp-del";
          deleteButton.type = "button";
          deleteButton.textContent = "Delete";
          deleteButton.setAttribute("aria-label", "Delete expense");

          row.appendChild(info);
          row.appendChild(deleteButton);
          expenseList.appendChild(row);

          if (visible) {
            visibleCount++;
            visibleTotal += expense.amount;
            categoryTotals[expense.category] += expense.amount;
          }
        });

        totalElement.textContent = formatAmount(visibleTotal);

        document.querySelectorAll(".cat-total").forEach(function (element) {
          const cat = element.dataset.cat;
          const label = cat.charAt(0).toUpperCase() + cat.slice(1);
          element.textContent = label + ": ";
          const value = document.createElement("strong");
          value.textContent = formatAmount(categoryTotals[cat]);
          element.appendChild(value);
        });

        emptyMessage.textContent = visibleCount
          ? ""
          : (expenses.length ? "No expenses match the current filters." : "No expenses yet.");
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();
        formError.textContent = "";

        const rawAmount = amountInput.value.trim();
        const amount = Number(rawAmount);
        const date = dateInput.value;

        if (!rawAmount || !Number.isFinite(amount) || amount <= 0) {
          formError.textContent = "Enter an amount greater than zero.";
          return;
        }

        if (!date) {
          formError.textContent = "Choose a date.";
          return;
        }

        const expense = {
          id: String(Date.now()) + "-" + Math.random().toString(36).slice(2),
          amount: amount,
          category: categoryInput.value,
          date: date,
          note: noteInput.value.trim()
        };

        expenses.unshift(expense);
        saveExpenses();
        formError.textContent = "";
        amountInput.value = "";
        render();
      });

      expenseList.addEventListener("click", function (event) {
        if (!event.target.classList.contains("exp-del")) return;

        const row = event.target.closest(".expense");
        if (!row) return;

        expenses = expenses.filter(function (expense) {
          return expense.id !== row.dataset.id;
        });
        saveExpenses();
        render();
      });

      [filterCategory, filterFrom, filterTo].forEach(function (control) {
        control.addEventListener("change", render);
      });

      render();
    })();
  </script>
</body>
</html>
